import json,datetime,re,os
os.chdir('/home/claude/sdeuniverses-site-')
K=[
("发生不是发现：全书的前提","本书反复检查一个没有说出口的前提：意思、作品、美都是“现成的”，读者、听众、观众只负责去发现、去欣赏。著者的看法是：意思不是在说话之前就躺在话里的，是在说的人和听的人之间一句一句过出来的；一部作品的意思不是作家写完就定了，是在一个又一个读者的读法里一手一手过出来的；一幅画的美不是挂在墙上等你，是你的眼睛和身体接住了它，它才在那一下里成了美。这叫发生。它不是否认语言、文学、艺术里有好东西，而是把这些好东西是怎么来的，重新讲给每一个不觉得自己懂的人听。","前言"),
("三大感觉里的 S·D·E","导论用摸、听、看三种最贴身的感觉讲 SDE：显露（Show，一样东西一层一层显出样子）、差异序列（Difference，一个差别接着一个差别走成一条路）、特征纠缠（Entanglement，人和物缠在一起拆不开）。三者不是三样东西，是同一件事的三个说法；每一种感觉里都含着完整的显露、差异序列与纠缠，不是一维对一种感觉，分开讲只是为了讲。第28章再用一块干裂的土地、灶边的哼唱、夜里一明一灭的绿光，把摸、听、看在日常里各走一遍，读者可以在自己的耳朵、眼睛和手上验证。","导论、第28章"),
("名字是把一串差别叫稳的显露","第1章讲名字不是先挂在东西上等人去认，而是一遍一遍叫出来、被接住、叫稳的：一家人给小黄狗叫“饭团”，叫了十几遍才稳。《駉》里十六个马名，一个名字对应一个差异；名字以最省的办法把一串差别切成一块。名字一旦被当真，会回过头来改写现实。“名字是手指，问题才是月亮”：贴标签是发现学的写法，看见名字怎样叫出来、叫出来以后怎样回头改写土壤，是发生学的写法。反例条件写在章末：若名字全都先于差别出现且从不因使用而改，这一章就错了。","第1章"),
("意思与语感：口气替字面多走一步","第2章讲同一句话缠着不同的人和场合，显出不同的意思：“吃饭了吗”“你来啦”“快到了”都不是词典里并排的选项。第3章讲语感：说话那一刻，在人、话、场合碰在一起的地方当场再显出来的一道差异边界，不是存起来的规则，也不是次数攒出来的库。字面越省，口气越得替它多走一步；说不上来的“对”落在这道缝上。书中引《SIO 语言发生学导论》给的语感定义，只取语感与自由律相连这一层。若语感完全由背诵量决定，与被谁回应无关，这一章就错了。","第2、3章"),
("语法是一代代人走出来的路，重复的是忍的次数","第4章讲语法是许多人说话的差别一代代沉下来、走成的组织起来的路；传开了不等于活下来，“扩散”和“器官化”是两件事，秦莉把后者叫作语法生育力，克里奥尔化的语言学细节书中标〔待核〕、只写成条件句。第5章讲重复：《硕鼠》三章只换四处，字越不变，换掉的那个字越重；《无衣》的“与子”在重复里亮出“一起”。若每一遍说完起点真的变了，是回写；若每一遍都回到原处、只剩消耗，是轮回，也就是转圈。","第4、5章"),
("比喻、接不上与翻译","第6章讲比喻带走的不是字，是承接的办法：死了的比喻是显露稳住了、差别消退了，让它复活就是把结论拆回过程再走一遍。第7章讲说得对救不了接不上：同样信息的两句话，接法不同，落成的事就不同。第8章讲母语不是可以脱下来换上的外衣，而是人与这门话之间的特征纠缠，翻译能搬过去的是字，搬不过去的是这门话缠着的人和日子；翻译了字，没翻译那一口乡音。书中《左传》垂陇之享、《1984》新话等引文，在附录 D 注明未逐字核对、不当原话引。","第6—8章"),
("孩子是被接住才开口的","第9章讲孩子不是学会了说话，是被一次次接住，才有了话，也有了自己：婴儿咿呀，妈妈慢半拍回应；阿芮的外婆哼两遍，阿芮就会了，还改了词；一个称呼“老四”走了一辈子。带差别的接住，比快而准的复读更能让孩子开口，这是本书读法。本章点名的两个“敌人”是两个“本来就在”：一台先在的语言机器和一个只会回放的录音机，它们都漏了被接住的那一来一回。若从不被回应、只听录音的孩子开口并不更晚，这一章就错了。","第9章"),
("谁在写：第一手与下一手","第10章讲一部作品不是作者写完就定了，是一手一手抄、念、转述、重读过出来的：连夜抄诗集的人付时间、付眼力，把诗存进手里；同屋一问回写给抄的人，诗才从纸上进到自我、再进到下一个人。交得下去的，不是抄得准，是付过代价之后有了自己的声音。章末引第384号结语：写下第一个字的人是第一手，你可以是下一手。第11章把同一个“愧”写成两版，骨架没变，文学让同一个发生在手、门、水里再显露一遍；两版读完若对“愧”的理解与做法毫无差别，这一章就错了。","第10、11章"),
("底库、碎镜与消失","第12章讲经典给你可能，不替你决定作品：母亲教女儿包饺子，口诀与手感各管一半，作品要从自己日子的摩擦里长出来；太顺要小心，太卡不必慌。第13章讲写成一个词，读者知道；写成一段起伏，读者经历，意识流里那条差异序列由读者自己来走、一次次被绊住。第14章讲美不在消失之前，在消失被看见的那一刻：黛玉焚稿之所以重，是因为前文读者一次次回头看过那些诗稿。若意识流的效果能完整还原成一张技法清单，照着写就得到同样的东西，第13章就错了。","第12—14章"),
("一个自由三种活法，结局已定发生未竟","第15章讲同一个“自由”落在想清楚（理念界）、过得去（现实界）、撑得住（自我界）三处，是落点不是性格，会随日子挪；大师教的是写下的那一半，靠的是活过而没写下的那一半。三本书对写走的是张力积累、形状改变、回写三拍。第16章讲情与悲：明知黛玉要死，读到葬花仍揪心，因为判词锁终点不锁路，结局虽定，发生未竟；同样的伤一代一代重演是轮回，“你可以”是回写。若只有终点、没有一步一步摩擦的故事也能同样揪心，这一章就错了。","第15、16章"),
("读者、普通人写与作者之问","第17章讲读是读者走的那条路：作者可以铺路、拦路、留台阶，迈步的是读的人，读者越多不等于读得越深，走过的读法会改写下一次读的起点；空白是留给读者的门缝，缺席是能回答的人不在了。第18章讲普通人写东西，是把日子里的物件一件件排成差别，让那段日子在字里显出来，先找那件既隔开又连着的东西。第19章问作者死了吗：作者、读者、文本在机器出现后成了人与机器缠出来的复合体，作者那一股里有提、生、沉三份活，提和沉可以分出去，生可以交给机器，唯有认下它、为它负责这一下分不出去。","第17—19章"),
("美与感动：第三样东西，有顺序","第20章讲美既不在东西身上，也不在看的人心里：东西、人、那一刻的日子缠在一起，发生了第三样东西，就是美；发生完看起来像本来就在。毛衣没变，你变了。第21章讲感动有顺序：先是身体被碰到，再是情绪理出路，最后整个人站进去，秦莉叫作感觉、情感、情境三情，层序律是它们依次亮起、被打乱时后亮的先熄。书里特别提醒：三情不对应显露、差异序列、纠缠，不要一对一配。哭了，不等于你曾在那里：催泪广告能让你哭，却记不起曾在那里。","第20、21章"),
("听见的美与看见的美","第22章讲音乐不在声音里，也不在乐谱上，而在一串声音被人接住、在几个活的身体之间走过的那一段里：同一首《祝你生日快乐》，在饭桌、会议室、追悼会上夸的东西变了三回；梅西安与陈其钢的师承是两条在走的生命相撞，撞出双方原来都没有的东西。第23章讲笔画可以断，气必须连；看画的深浅，看的是你有没有出手接；命名太早会把看截在第一层，叫抢先覆盖；承重不等于负荷，技术的辛苦有外部标准可对，背负的判断没有。","第22、23章"),
("意料之外、一下决断与破损也美","第24章讲来得随机、走得有理，二刷时有理的结局比巧合解围的结局更被认可；影像原时是在剥离叙事中发生的，也可能不发生；短视频是“糖”，不一定有“骨”。第25章讲下刀、扛住、护住：下刀是方向与做法在同一刀里一起显出，扛住是“够了”这条线由自己认下、不可撤回，护住是回写需要时间；挑选发生在东西做好之后，裁决发生在东西还不存在的时候。第26章讲补不是回到原样，是给张力一个出口；审丑不是赞美丑，是承认发生现场的难看，因为回写正发生在那里。","第24—26章"),
("禁令作为留白，艺术是允许出来的","第27章讲限制不是创造的墙，是创造的地板：窑火要停、字不可写满、第一个方案通不过，都是约束在逼出新路；这与只管“能做什么”的构成性规则不同，多出一维时相，也就是什么时候必须停。第28章讲小事也是一次完整的发生，叫微发生（第244号）；“会”是手、琴、老师缠在一起、被允许走完难看阶段后长出来的，不给发生配“天赋”这台先在的机器。艺术不是教出来的，是允许出来的；若从不被允许画得不像、唱得走音的人，成年后同样自在地进入艺术，这一章就错了。","第27、28章"),
("这本书在什么情形下就错了，和哪些地方没有核实","全书每一章末尾都写明“什么情况下这一章错了”；结语写：若一句话、一本书、一首歌，在没有人接、没有人走、没有人交下去的情况下仍同样活着，全书的承重判断就错了。结语的主线是：被记得，是交付成功的回执。书里的阿芮、贺峻等人物与场景是设想的例子，不承担证据；凡标明“按本书读法、不是秦莉的原话”的，须与秦莉的原话分开；附录 D〔待核〕清单集中列出了未逐字核对的引文、史实、数据与书目信息，核不到的不加引号、不当原话。","结语、附录D"),
]
L=[len(re.sub(r'\s','',x)) for _,x,_ in K]; assert len(K)>=10 and min(L)>=170,L
today=datetime.date.today().isoformat()
kp={'no':539,'title':'SDE思想与文学艺术','built':today,'items':[{'t':t,'x':x,'ch':c} for t,x,c in K]}
open('public/books/m/539/keypoints.json','w',encoding='utf-8').write(json.dumps(kp,ensure_ascii=False)+'\n')
ap='public/books/agents.json'; reg=json.load(open(ap,encoding='utf-8'))
name='过手'; assert not [k for k,v in reg['agents'].items() if v.get('name')==name and k!='539'], 'name taken'
reg['agents']['539']={'name':name,'epithet':'先问这件事走到了哪一手，再问谁接、接成了什么，最后问你下一手怎么过',
'intro':"我从《SDE思想与文学艺术》里来，名字取自全书的核心动作：过手——一句话、一首诗、一幅画，都不是现成的东西等人去发现，而是在说的人和听的人、写的人和读的人、做的人和看的人之间，一手一手过出来的。你可以带一件事来：一句让你觉得“说不上来的对”的话，一首你抄过念过的诗，一件让你动了心的旧物，一段你让 AI 帮你写、最后只认下一句的话，或者你对“美是客观的”“艺术要有天赋”这类说法哪里不对劲。我先陪你问三句：这件事现在走到了哪一手？谁接住了它，接成了什么？你下一手准备怎么过？书里的人物与场景是设想的例子，不当证据；凡标〔待核〕的引文集中在附录 D，我不把它们说成已核实，也不替任何人下好坏的定性，不编造引文、数字和原话。",
'starts':{
"read":"第5章说重复的不是字，是忍的次数。请用一个日常例子（比如一位爸爸天天喊“把鞋摆好”）给我讲一遍：怎样的重复是回写，怎样的重复只是转圈？每一遍里该有哪一处在动？",
"apply":"我让 AI 帮我写了一段话，最后只认下其中一句。照第19章，我先要分清：提、生、沉三份活里，我自己留下了哪一份？认下它、为它负责，我付了什么？",
"cut":"每一章末尾都写了“什么情况下这一章错了”。请挑第21章或第25章，你认为它的反例条件最容易发生在哪里？结语里全书承重判断会错的条件，你觉得离现实有多远？",
"clash":"有人反驳：美、语感、感动都不过是个人主观，发生学不过把“主观”换了个名字，没有增量。请按第20章和第21章回应：“第三样东西”和“层序律”到底多说了什么？书里最弱的一环是哪一处？"}}
for k in('updatedAt','updated'):
    if k in reg: reg[k]=datetime.datetime.now(datetime.timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ') if k=='updatedAt' else today
open(ap,'w',encoding='utf-8').write(json.dumps(reg,ensure_ascii=False,indent=1)+'\n')
print('ok',L)
